import 'dart:convert';import 'dart:io';import 'legacy_plugin_invocation.dart';import 'legacy_plugin_result.dart';import 'legacy_runtime_collector.dart';import 'legacy_runtime_request.dart';import 'python_executor.dart';
class ProcessPythonExecutor implements PythonExecutor{const ProcessPythonExecutor({required this.pythonExecutable,required this.workerScriptPath,this.requestHandler});final String pythonExecutable,workerScriptPath;final LegacyRuntimeRequestHandler? requestHandler;@override Future<LegacyPluginResult>invoke(LegacyPluginInvocation invocation)async{final c=LegacyRuntimeCollector();final temp=await Directory.systemTemp.createTemp('addko-python-');final file=File('${temp.path}${Platform.pathSeparator}context.json');try{await file.writeAsString(jsonEncode(invocation.toJson()),flush:true);final process=await Process.start(pythonExecutable,[workerScriptPath,file.path],workingDirectory:invocation.addonPath,environment:{...Platform.environment,'PYTHONUTF8':'1','PYTHONDONTWRITEBYTECODE':'1'},runInShell:false);final stdoutDone=process.stdout.transform(utf8.decoder).transform(const LineSplitter()).asyncMap((line)async{final r=LegacyRuntimeRequest.tryParse(line);if(r==null){c.consumeStdoutLine(line);return;}Object? result=r.defaultValue;if(requestHandler!=null){try{result=await requestHandler!(r);}on Object catch(e){c.consumeStderrLine('GUI request ${r.method} failed: $e');}}process.stdin.writeln(jsonEncode({'request_id':r.id,'result':result}));await process.stdin.flush();}).drain<void>();final stderrDone=process.stderr.transform(utf8.decoder).transform(const LineSplitter()).forEach(c.consumeStderrLine);final exit=await process.exitCode;await Future.wait([stdoutDone,stderrDone]);await process.stdin.close();return c.build(exitCode:exit);}on ProcessException catch(e){c.consumeStderrLine(e.toString());return c.build(exitCode:-1);}finally{if(await temp.exists())await temp.delete(recursive:true);}}}
class PythonExecutableResolver{const PythonExecutableResolver();Future<String?>resolve()async{final configured=Platform.environment['ADDKO_PYTHON']?.trim();final candidates=<String>[if(configured!=null&&configured.isNotEmpty)configured,if(Platform.isWindows)'python.exe' else 'python3',if(Platform.isWindows)'py.exe' else 'python'];for(final c in candidates){try{final r=await Process.run(c,const ['--version'],runInShell:false);if(r.exitCode==0)return c;}on ProcessException{}}return null;}}
